uint32_t ma2_bot_local_flags(uint32_t player);
    {   /* RECOMP_JET_TRACE: every change of an actor's jet bit (actor+0x268 bit15), with the caller */
        static int on = -1;
        if (on < 0) { const char *e = getenv("RECOMP_JET_TRACE"); on = e && *e && *e != '0'; }
        if (on) {
            uint32_t was = (MEM32(ecx + 0x268) >> 15) & 1u, now = LO8(eax) & 1u;
            if (was != now) {
                fprintf(stderr, "[JET-BIT] t=%.4f actor=%08X %u->%u caller=%08X\n", (double)clock() / (double)CLOCKS_PER_SEC, ecx, was, now, MEM32(esp));
            }
        }
    }
    {   /* RECOMP_JET_TRACE=2: every jet-thrust update while the jet bit is on -- held flag, caller */
        static int lvl = -1, n;
        if (lvl < 0) { const char *e = getenv("RECOMP_JET_TRACE"); lvl = e ? atoi(e) : 0; }
        if (lvl >= 2 && n < 4000 && (MEM32(ecx + 0x268) & 0x8000u)) {
            n++;
            fprintf(stderr, "[JET-UPD] t=%.4f actor=%08X held=%u ret=%08X bits=%08X\n", (double)clock() / CLOCKS_PER_SEC, ecx, MEM8(esp + 4), MEM32(esp), MEM32(ecx + 0x268));
        }
    }
    ma2_tank_fixed_forget(edi); /* host phase only */
    ma2_tank_fixed_forget(ecx); /* host phase only */
    ma2_tank_fixed_forget(ecx); /* host phase only */
